{
  "tests": [
    {
      "id": "R4-01",
      "rule": "R4",
      "kind": "boundary",
      "title": "Checkout succeeds when item quantity exactly equals available stock",
      "steps": [
        {
          "method": "POST",
          "path": "/api/carts",
          "body": null,
          "save_id_as": "cart",
          "expect_status": 201
        },
        {
          "method": "POST",
          "path": "/api/carts/{cart}/items",
          "body": {
            "product_id": 5,
            "qty": 3
          },
          "expect_status": 200
        },
        {
          "method": "POST",
          "path": "/api/carts/{cart}/checkout",
          "body": null,
          "expect_status": 200
        },
        {
          "method": "GET",
          "path": "/api/products",
          "expect_status": 200,
          "checks": [
            {
              "field": "[id=5].stock",
              "op": "equals",
              "value": "0",
              "rule": "R4",
              "why": "Purchasing 3 units of product 5 with 3 available stock leaves 0 stock remaining."
            }
          ]
        }
      ]
    },
    {
      "id": "R4-02",
      "rule": "R4",
      "kind": "boundary",
      "title": "Checkout fails with 409 OUT_OF_STOCK when item quantity exceeds available stock",
      "steps": [
        {
          "method": "POST",
          "path": "/api/carts",
          "body": null,
          "save_id_as": "cart",
          "expect_status": 201
        },
        {
          "method": "POST",
          "path": "/api/carts/{cart}/items",
          "body": {
            "product_id": 5,
            "qty": 4
          },
          "expect_status": 200
        },
        {
          "method": "POST",
          "path": "/api/carts/{cart}/checkout",
          "body": null,
          "expect_status": 409,
          "checks": [
            {
              "field": "detail.code",
              "op": "equals",
              "value": "OUT_OF_STOCK",
              "rule": "R4",
              "why": "Quantity 4 exceeds available stock 3, so checkout fails with OUT_OF_STOCK."
            }
          ]
        },
        {
          "method": "GET",
          "path": "/api/products",
          "expect_status": 200,
          "checks": [
            {
              "field": "[id=5].stock",
              "op": "equals",
              "value": "3",
              "rule": "R4",
              "why": "Failed checkout must not change the stock of any product."
            }
          ]
        }
      ]
    },
    {
      "id": "R4-03",
      "rule": "R4",
      "kind": "error",
      "title": "Multi-item checkout failure preserves stock for all products in cart",
      "steps": [
        {
          "method": "POST",
          "path": "/api/carts",
          "body": null,
          "save_id_as": "cart",
          "expect_status": 201
        },
        {
          "method": "POST",
          "path": "/api/carts/{cart}/items",
          "body": {
            "product_id": 3,
            "qty": 2
          },
          "expect_status": 200
        },
        {
          "method": "POST",
          "path": "/api/carts/{cart}/items",
          "body": {
            "product_id": 5,
            "qty": 4
          },
          "expect_status": 200
        },
        {
          "method": "POST",
          "path": "/api/carts/{cart}/checkout",
          "body": null,
          "expect_status": 409,
          "checks": [
            {
              "field": "detail.code",
              "op": "equals",
              "value": "OUT_OF_STOCK",
              "rule": "R4",
              "why": "Checkout fails because product 5 quantity exceeds available stock."
            }
          ]
        },
        {
          "method": "GET",
          "path": "/api/products",
          "expect_status": 200,
          "checks": [
            {
              "field": "[id=3].stock",
              "op": "equals",
              "value": "5",
              "rule": "R4",
              "why": "Stock of in-stock item 3 must remain unchanged after failed checkout."
            },
            {
              "field": "[id=5].stock",
              "op": "equals",
              "value": "3",
              "rule": "R4",
              "why": "Stock of out-of-stock item 5 must remain unchanged after failed checkout."
            }
          ]
        }
      ]
    }
  ]
}

